figure (1) %[output:35d8550c]

t = linspace (-pi, pi, 50);
y = sin(t) %[output:1953d262]
plot(t, y, '-r', 'LineWidth', 1.5, 'MarkerSize', 6); %[output:74e69d37]
grid on; %[output:74e69d37]

xlim([-pi pi]); %[output:74e69d37]
ylim([-1.1 1.1]); %[output:74e69d37]

xlabel ('t'); %[output:74e69d37]
ylabel ('y(t)'); %[output:74e69d37]
title('y(t) = sin(t)'); %[output:74e69d37]

legend('y(t) = sin(t)', 'Location', 'best'); %[output:74e69d37]




figure(2)

x = linspace(-pi, pi, 50);

y1 = -x.^2 + 9;
y2 = x.^3 - 2*x.^2 - 9;

plot(x, y1, '-r', 'LineWidth', 1.5); %[output:9c5040c5]
hold on; %[output:9c5040c5]
plot(x, y2, '-b', 'LineWidth', 1.5); %[output:9c5040c5]
hold off; %[output:9c5040c5]
grid on; %[output:9c5040c5]

xlim([-pi pi]); %[output:9c5040c5]
ylim([min([y1 y2])-1 max([y1 y2])+1]); %[output:9c5040c5]

xlabel('x'); %[output:9c5040c5]
ylabel('y'); %[output:9c5040c5]
title('Funkcijų grafikai'); %[output:9c5040c5]

legend('y(x) = -x^2 + 9', ... %[output:group:3cd42d33] %[output:9c5040c5]
    'y(x) = x^3 - 2x^2 - 9', ... %[output:9c5040c5]
    'Location', 'best'); %[output:group:3cd42d33] %[output:9c5040c5]
%%
G = [8 7 9 4 6 8; 7 5 9 6 8 7; 7 6 8 9 10 9; 9 7 8 7 7 9];

figure (3)

subplot (2, 1, 1); %[output:554b36ef]
bar (G) %[output:554b36ef]

xlim([0 5]); %[output:554b36ef]
ylim([0 10]); %[output:554b36ef]
xlabel ('LD numeris'); %[output:554b36ef]
ylabel ('LD ivertinimas'); %[output:554b36ef]
title ('a)'); %[output:554b36ef]
legend('Jonas', 'Matas', 'Andrius', 'Linas', 'Tomas', 'Lukas', 'Location', 'eastoutside'); %[output:554b36ef]

subplot(2,1,2); %[output:554b36ef]

vidurkiai = mean(G,1);
stem(1:6, vidurkiai); %[output:554b36ef]

xlim([0 7]); %[output:554b36ef]
ylim([0 10]); %[output:554b36ef]
xlabel('Studentas'); %[output:554b36ef]
ylabel('LD ivertinimu vidurkis'); %[output:554b36ef]
title('b)'); %[output:554b36ef]
%%
figure(4)

A = 4.5;
f = 6;
t = [0:0.001:1.5];
b = 1;
U1 = 3;
U2 = 1.5;

st = A * cos(2*pi*f*t);

n = b * rand(size(t));
s = st + n;

sf = s;
sf(abs(sf) < U2) = 0;

subplot(2,1,1); %[output:04fba3cf]
hold on; %[output:04fba3cf]
plot(t, s, 'c', 'LineWidth', 1.5); %[output:04fba3cf]
plot(t, sf, 'm', 'LineWidth', 1.5); %[output:04fba3cf]
yline(U1, 'k:', 'U_1', 'LineWidth', 1.2); %[output:04fba3cf]
yline(U2, 'k:', 'U_2', 'LineWidth', 1.2); %[output:04fba3cf]
grid on; %[output:04fba3cf]

xlabel('Laikas (s)', 'Color', 'b', 'FontSize', 11, 'FontWeight', 'bold'); %[output:04fba3cf]
ylabel('Amplitudė (V)', 'Color', 'b', 'FontSize', 11, 'FontWeight', 'bold'); %[output:04fba3cf]
title('Pradinis ir filtruotas signalai'); %[output:04fba3cf]
legend('Pradinis signalas', 'Filtruotas signalas', 'U_1 riba', 'U_2 riba', 'Location', 'southwest'); %[output:04fba3cf]
xlim([0 1.5]); %[output:04fba3cf]
ylim([-6 6]); %[output:04fba3cf]


subplot(2,1,2); %[output:04fba3cf]
hold on; %[output:04fba3cf]
idx = s > U1;
stem(t(idx), s(idx), 'Color', [0 0.45 0.74], 'LineWidth', 1); %[output:04fba3cf]

minIdx = islocalmin(s);
maxIdx = islocalmax(s);

plot(t(minIdx), s(minIdx), '^', 'MarkerSize', 6, 'MarkerFaceColor', 'y', 'MarkerEdgeColor', 'k'); %[output:04fba3cf]
plot(t(maxIdx), s(maxIdx), '^', 'MarkerSize', 6, 'MarkerFaceColor', 'y', 'MarkerEdgeColor', 'k'); %[output:04fba3cf]

yline(U1, 'k:', 'U_1', 'LineWidth', 1.2); %[output:04fba3cf]
grid on; %[output:04fba3cf]

xlabel('Laikas (s)', 'Color', 'b', 'FontSize', 11, 'FontWeight', 'bold'); %[output:04fba3cf]
ylabel('Amplitudė (V)', 'Color', 'b', 'FontSize', 11, 'FontWeight', 'bold'); %[output:04fba3cf]
title('Diskretinis signalas, viršijantis U_1 ribą'); %[output:04fba3cf]
legend('Signalas, s > U_1', 'Minimumai ir maksimumai', 'U_1 riba', 'Location', 'southwest'); %[output:04fba3cf]

xlim([0 1.5]); %[output:04fba3cf]
ylim([-6 6]); %[output:04fba3cf]

